/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void hobp_bus_err_add (Hobp_Bus_Error_Code code)
{  
  UInt8 ptr = hobp_bus_vars.err.count % HOBP_BUS_ERR_BUFF_SIZE ;
 
  hobp_bus_vars.err.code[ptr] = code ;

  hobp_bus_vars.err.count++ ;

  hobp_bus_vars.do_save = TRUE ;

  #if DBG_HOBP_BUS == 1
    hobp_bus_dbg_print("\nHobp_Bus Err:" , &code , 1) ; 
    hobp_bus_dbg_print("\n" , NULL , NULL) ; 
  #endif
}



